import java.util.*;
public class Main {
    static class NotFoundException extends RuntimeException {}
    static class UnauthorizedException extends RuntimeException {}
    static class ConflictException extends RuntimeException {}
    static int handle(Exception e){
        if(e instanceof NotFoundException) return 404;
        if(e instanceof UnauthorizedException) return 401;
        if(e instanceof ConflictException) return 409;
        return 500;
    }
    public static void main(String[] a){
        Exception[] xs={new NotFoundException(),new UnauthorizedException(),new ConflictException(),new RuntimeException("boom")};
        for(Exception e:xs) System.out.println(e.getClass().getSimpleName()+" -> "+handle(e));
    }
}
